Object.assign(defaults,structuredClone(plannerSeed));function ensurePlanner(){for(const [k,v] of Object.entries(plannerSeed))if(state[k]===undefined)state[k]=structuredClone(v)}ensurePlanner();let journeyFilter='all',journeyRange='full';
const types={income:['Net income / repayments','var(--ink)'],tax:['Tax','#d64a48'],trade:['Transactions','#3977c2'],travel:['Travel / reviews','#cd842c']};
function extraUKNights(status){const nights=new Set();for(const t of state.travelRecords.filter(t=>t.country==='UK'&&(t.status||'Planned')===status)){let d=new Date(t.start+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+1);const end=new Date(t.end+'T00:00:00Z');for(;d<=end;d.setUTCDate(d.getUTCDate()+1)){const stamp=d.toISOString().slice(0,10);if(stamp>='2026-04-06'&&stamp<'2027-04-06')nights.add(stamp)}}return nights.size}
function recAmount(){return Math.max(0,Math.min(20000-ledger.allowances.isa,available('cash')))}
function timelineData(){const dates=state.journey.flatMap(e=>[e.date,e.end||e.date]).sort();const start=journeyRange==='near'?'2026-10-17':(dates[0]<'2026-09-01'?dates[0]:'2026-09-01'),end=journeyRange==='near'?'2027-02-01':(dates[dates.length-1]>'2027-06-30'?dates[dates.length-1]:'2027-06-30');return{start,end,events:state.journey.filter(e=>(journeyFilter==='all'||e.kind===journeyFilter)&&e.date>=start&&e.date<=end).sort((a,b)=>a.date.localeCompare(b.date))}}
function timeline(){const {start,end,events}=timelineData(),w=Math.max(300,Math.min(664,window.innerWidth-48,document.querySelector('#screen').clientWidth-48)),left=64,right=w-24,ts=s=>new Date(s+'T00:00:00Z').getTime(),x=s=>left+(ts(s)-ts(start))/(ts(end)-ts(start))*(right-left),maxAmount=Math.max(1,...events.map(e=>Math.abs(e.amount||0))),ys={tax:55,income:111,trade:167,travel:223};let month=new Date(start+'T00:00:00Z');month.setUTCDate(1);const span=(ts(end)-ts(start))/86400000,monthStep=span>3650?60:span>730?12:span>370?3:1;let ticks='';while(month.getTime()<=ts(end)){const d=month.toISOString().slice(0,10);if(d>=start){const px=x(d);ticks+=`<line x1="${px}" y1="23" x2="${px}" y2="251" class="grid-line"/><text x="${px}" y="277" text-anchor="middle">${month.toLocaleDateString('en-GB',{month:'short',...(monthStep>1?{year:'2-digit'}:{}),timeZone:'UTC'})}</text>`}month.setUTCMonth(month.getUTCMonth()+monthStep)}const now=x('2026-10-17');return `<div class="journey-controls"><div class="journey-filters" aria-label="Event type">${[['all','All'],['tax','Tax'],['income','Income'],['trade','Trades'],['travel','Travel']].map(([k,label])=>`<button data-journey-filter="${k}" aria-pressed="${journeyFilter===k}">${label}</button>`).join('')}</div><label class="range-label" for="journey-range">Range<select id="journey-range"><option value="full" ${journeyRange==='full'?'selected':''}>Whole journey</option><option value="near" ${journeyRange==='near'?'selected':''}>Next 3½ months</option></select></label></div><svg class="journey-chart" viewBox="0 0 ${w} 290" aria-label="Investment timeline. Choose an event for its amount, status and tax details." role="group">${ticks}${Object.entries(ys).map(([k,y])=>`<text x="2" y="${y+4}" class="lane-label">${{tax:'Tax',income:'Income',trade:'Trades',travel:'Travel'}[k]}</text><line x1="${left}" y1="${y}" x2="${right}" y2="${y}" class="lane-line"/>`).join('')}<line x1="${now}" x2="${now}" y1="19" y2="250" class="today-line"/><text x="${now}" y="12" text-anchor="middle">Today</text>${events.map((e,i)=>{const px=x(e.date)+(e.id==='it'?7:e.id==='cgt'?-7:0),y=ys[e.kind]+(e.id==='it'?12:0),rad=e.amount?5+Math.sqrt(Math.abs(e.amount)/maxAmount)*13:6,c=types[e.kind][1],label=`${when(e.date)} · ${e.name} · ${e.amount?money(e.amount):e.status}`;return `<g role="button" tabindex="0" data-event="${esc(e.id)}" aria-label="${esc(label)}" class="event-node"><title>${esc(label+' · '+e.owner+' · '+e.status)}</title>${e.end?`<line x1="${px}" x2="${Math.min(right,x(e.end))}" y1="${y}" y2="${y}" stroke="${c}" stroke-width="7" opacity=".3"/>`:''}${e.low?`<path d="M${px} ${y-28}v56m-5-56h10m-10 56h10" stroke="${c}" stroke-width="1.5"/>`:''}<circle cx="${px}" cy="${y}" r="${rad}" fill="${c}" ${/Estimate|estimate|Planned|Proposed|Draft/.test(e.status)?'fill-opacity=".72" stroke="'+c+'" stroke-dasharray="2 2"':''}/></g>`}).join('')}</svg><div id="event-preview" class="event-preview" aria-live="polite">Hover, focus or tap an event. Circle size shows value; whiskers show an estimated amount range.</div><div class="timeline-legend">${Object.entries(types).map(([k,[label,c]])=>`<span><i style="background:${c}"></i>${label}</span>`).join('')}</div><p class="fine">Illustrative events. Trades show proceeds or cost, not gains. Income is net of the stated tax estimate. Planned amounts and dates can change.</p>`}
function upcomingList(kind){return state.journey.filter(e=>e.kind===kind&&e.date>='2026-10-17').sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<button class="planner-row" data-event="${esc(e.id)}"><div><strong>${e.amount?money(e.amount):when(e.date)} <span>${esc(e.name)}</span></strong><small>${when(e.date)} · ${esc(e.owner)} · ${esc(e.status)}</small></div><span>→</span></button>`).join('')}
home=function(){ensurePlanner();const recommend=recAmount();return `<section class="planner-wealth"><h1>Your wealth</h1><div class="planner-total">${money(wealth())}</div><button class="text-link" data-command="basis">How it’s counted ↗</button></section><section class="planner-available"><h2>Available to invest</h2><div class="available-row"><strong>${money(cashTotal()+liquidInvestments())}</strong><span>Total liquid assets <small>Includes investments to sell; tax and settlement apply</small></span></div><div class="available-row"><strong>${money(spare())}</strong><span>Cash marked available <small>After spending, tax reserve and committed cash</small></span></div><div class="reviewed-opportunity"><span class="small-label">ILLUSTRATIVE PARTNER-REVIEWED SUGGESTION</span><p>${recommend?'Invest <strong>'+money(recommend)+'</strong> in your stocks & shares ISA.':'No unused ISA contribution amount is available in this example.'}</p><small>${recommend?'This uses recorded ISA headroom and available personal cash. Eligible ISA income and gains are sheltered from UK tax. Eligibility, fund choice and suitability still need confirmation.':'Add your current allowances and cash needs before planning more.'}</small>${recommend?'<button class="text-link" id="plan-isa">Plan this investment →</button>':''}</div></section><section class="inline-doc"><label for="quick-document"><strong>Drop a document here.</strong><span>Share purchases, grants, agreements or flights.</span><input id="quick-document" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv,.doc,.docx,.xls,.xlsx"></label><p>Or forward to <button class="text-link" id="inbox-info">ron@ron.com</button> <small>Planned inbox</small></p><small>Prototype: file details only. Document analysis and email intake aren’t connected.</small></section><section class="planner-timeline"><div class="section-heading"><h2>Your timeline</h2><button class="text-link" id="add-event">Add an event ↗</button></div>${timeline()}</section><section class="upcoming-block"><h2>Upcoming disbursements</h2>${upcomingList('income')}</section><section class="upcoming-block"><h2>Upcoming tax payments</h2>${upcomingList('tax')}</section><section class="upcoming-block"><h2>Upcoming transactions</h2>${upcomingList('trade')}</section><section class="planner-travel"><div class="section-heading"><h2>Travel & residence</h2><button class="text-link" id="travel-plan">Add travel ↗</button></div><div class="night-count"><strong>132</strong><span>UK midnights recorded<small>Illustrative 2026/27 record · not a residence decision</small></span></div><p>${state.travelRecords.length?state.travelRecords.length+' additional itinerary record(s): '+extraUKNights('Recorded')+' recorded and '+extraUKNights('Planned')+' planned UK calendar nights for 2026/27, awaiting reconciliation.':'Planned: 36 more UK midnights in the sample itinerary.'} Your personal limit has not been confirmed by an adviser.</p><button class="planner-row" data-event="review"><div><strong>15 Feb 2027 <span>Review the planned move and IHT position</span></strong><small>Before the proposed 1 March departure</small></div><span>→</span></button><p class="fine">An itinerary is evidence, not a tax conclusion. Leaving the UK can leave continuing tax and IHT exposure. The full residence tests and history need review.</p></section><section class="needs"><div class="section-heading"><h2>Tasks</h2><span>${outstanding().length} actions · 2 examples</span></div><button class="task-row" data-filing="accounts"><div><strong>Review the company accounts example</strong><span>£2.75m assets · £2.4m creditors · full draft available</span></div><span>→</span></button><button class="task-row" data-filing="personal"><div><strong>Review the personal tax return example</strong><span>£18,200 estimated tax · full draft available</span></div><span>→</span></button>${outstanding().map(([a,b,c])=>`<button class="task-row" data-command="${c}"><div><strong>${a}</strong><span>${b}</span></div><span>→</span></button>`).join('')}</section><section class="background-work"><h2>Being handled</h2><p>Documents awaiting review: ${state.docs.length}. Investment requests: ${state.requests.length}. Nothing has been sent or filed by this prototype.</p></section>`};
function eventPreview(e){return `<strong>${when(e.date)} · ${esc(e.name)}</strong><span>${e.amount?money(e.amount):''}${e.low?' · range '+money(e.low)+'–'+money(e.high):''} · ${esc(e.owner)} · ${esc(e.status)}</span>`}function eventDetail(id){const e=state.journey.find(e=>e.id===id);if(!e)return;open(`<span class="small-label">${esc(types[e.kind][0])}</span><h2>${esc(e.name)}</h2><div class="event-money">${e.amount?money(e.amount):when(e.date)}</div><p>${when(e.date)}${e.end?' to '+when(e.end):''} · ${esc(e.owner)}<br>${esc(e.status)}</p>${e.low?'<p>Estimated range: '+money(e.low)+'–'+money(e.high)+'. The whisker marks this uncertainty.</p>':''}${e.gross!==undefined?`<dl class="review-list"><dt>Gross</dt><dd>${money(e.gross)}</dd><dt>Tax provision</dt><dd>${money(e.tax)}</dd><dt>Net amount</dt><dd>${money(e.amount)}</dd></dl>`:''}${e.gain!==undefined?'<p>Sale proceeds include a sample '+money(e.gain)+' gain. They are different amounts.</p>':''}<p>${esc(e.note)}</p><p class="fine">Illustrative planning record. This does not execute a transaction, set a legal deadline or confirm a liability.</p>`)}
function quickIntake(file){if(!file)return;state.docs.push({id:crypto.randomUUID(),name:file.name,size:file.size,kind:/flight|itinerary|boarding/i.test(file.name)?'Travel evidence':/eis/i.test(file.name)?'EIS document':/emi/i.test(file.name)?'EMI grant':/option/i.test(file.name)?'Options agreement':'Document to identify',owner:'Partner to confirm',created:new Date().toISOString()});persist();render();note('File details added. Analysis is not connected in this mock-up.')}
function addEvent(travel=false){open(`<h2>${travel?'Add planned travel.':'Add a planning event.'}</h2><form id="event-form"><label for="event-name">${travel?'Country / itinerary':'What is happening?'}</label><input id="event-name" required placeholder="${travel?'Australia':'Sell shares, receive income…'}">${travel?'<label for="travel-country">Country</label><select id="travel-country"><option value="UK">United Kingdom</option><option value="AU">Australia</option><option value="other">Other</option></select><label for="travel-status">Record</label><select id="travel-status"><option>Planned</option><option>Recorded</option></select>':`<label for="event-kind">Type</label><select id="event-kind"><option value="trade">Transaction</option><option value="income">Income</option><option value="tax">Tax</option><option value="travel">Travel / review</option></select><label for="event-owner">Who?</label><select id="event-owner"><option>Personal</option><option>Company</option></select><label for="event-amount">Estimated amount (£)</label><input id="event-amount" type="number" min="0" step="0.01" required>`}<label for="event-date">${travel?'Arrival / start date':'Planned date'}</label><input id="event-date" type="date" required><label for="event-end">${travel?'Departure / end date':'End date, if a range'}</label><input id="event-end" type="date" ${travel?'required':''}><p class="error" id="event-error" role="alert"></p><button class="primary wide">Save ${travel?'itinerary':'event'} (demo)</button><p class="fine">${travel?'Calendar dates only. No residence status or IHT exit date is calculated.':'This is a planned event, not a submitted order or confirmed tax bill.'}</p></form>`);$('#event-form').onsubmit=e=>{e.preventDefault();const start=$('#event-date').value,end=$('#event-end').value;if(end&&end<start){$('#event-error').textContent='The end date must be on or after the start date.';return}const name=$('#event-name').value.trim();if(!name)return;const record={id:crypto.randomUUID(),date:start,end:end||undefined,kind:travel?'travel':$('#event-kind').value,name,owner:travel?'Personal':$('#event-owner').value,amount:travel?0:Number($('#event-amount').value),status:travel?$('#travel-status').value+' dates · not reviewed':'Planned · not reviewed',note:travel?'User-added calendar itinerary. Night-counting and residence implications require review.':'User-added planning event. No transaction or tax computation was executed.'};state.journey.push(record);if(travel)state.travelRecords.push({name,start,end,country:$('#travel-country').value,status:$('#travel-status').value,nights:Math.round((new Date(end)-new Date(start))/86400000)});persist();close();render();note('Planning event saved locally.')}}
const previousTaxPage=taxPage;taxPage=function(){ensurePlanner();let html=previousTaxPage();html=html.replace('What’s left for 2026/27','Your limits for 2026/27');html=html.replace(/<details class="allowance">([\s\S]*?)<\/details>/g,(all,body)=>{const summary=body.match(/<summary>([\s\S]*?)<\/summary>/)[1],bar=body.match(/<div class="limit-bar">[\s\S]*?<\/div>/)[0],copy=body.match(/<p>[\s\S]*?<\/p>/)[0];const amounts=copy.match(/<p>(.*?) recorded against (.*?)\./);return `<div class="limit-chart">${summary}${bar}${amounts?'<small>'+amounts[1]+' used / '+amounts[2]+' annual limit</small>':''}<details><summary>What this means</summary>${copy}</details></div>`});return html};
const previousInvestDetails=investDetails;investDetails=function(){previousInvestDetails();const select=$('#horizon');select.insertAdjacentHTML('afterend','<label for="disposal-date">Planned disposal date, if you have one</label><input id="disposal-date" type="date" min="2026-10-18"><p class="fine">Optional. Holding periods and planned sales affect tax planning.</p>');const submit=$('#invest-form').onsubmit;$('#invest-form').onsubmit=e=>{investment.disposal=$('#disposal-date').value;submit(e)}};
const previousInvestReview=investReview;investReview=function(){previousInvestReview();if(investment.disposal)$('#dialog-content .review-list').insertAdjacentHTML('beforeend','<dt>Planned disposal</dt><dd>'+when(investment.disposal)+'</dd>');const send=$('#send-plan').onclick;$('#send-plan').onclick=()=>{const copy={...investment};if(copy.disposal){state.journey.push({id:crypto.randomUUID(),date:copy.disposal,kind:'trade',name:'Planned disposal: '+copy.name,owner:copy.source==='ficcash'?'Company':'Personal',amount:0,cost:copy.amount,status:'Planning placeholder · value to assess',note:'Future sale proceeds, gain and tax have not been calculated. See the planning request for the original proposed investment amount.'})}send()}};
const plannerBaseBind=bind;bind=function(){ensurePlanner();plannerBaseBind();document.querySelectorAll('[data-event]').forEach(b=>{const e=state.journey.find(e=>e.id===b.dataset.event)||window.ronDerivedEvents?.().find(e=>e.id===b.dataset.event);b.onclick=()=>eventDetail(b.dataset.event);if(b.classList.contains('event-node')){b.onmouseenter=b.onfocus=()=>{$('#event-preview').innerHTML=eventPreview(e)};b.onkeydown=k=>{if(k.key==='Enter'||k.key===' '){k.preventDefault();eventDetail(b.dataset.event)}}}});document.querySelectorAll('[data-journey-filter]').forEach(b=>b.onclick=()=>{journeyFilter=b.dataset.journeyFilter;render()});if($('#journey-range'))$('#journey-range').onchange=e=>{journeyRange=e.target.value;render()};if($('#quick-document')){$('#quick-document').onchange=e=>quickIntake(e.target.files[0]);const zone=$('.inline-doc label, .document-drop label');zone.ondragover=e=>e.preventDefault();zone.ondrop=e=>{e.preventDefault();quickIntake(e.dataTransfer.files[0])}}if($('#inbox-info'))$('#inbox-info').onclick=()=>open('<h2>One inbox for the paperwork.</h2><p>The proposed address is ron@ron.com. It would receive investment documents and flight confirmations for analysis and professional review.</p><p class="notice-box">The inbox is not connected. Don’t send real documents to it from this preview.</p>');if($('#add-event'))$('#add-event').onclick=()=>addEvent();if($('#travel-plan'))$('#travel-plan').onclick=()=>addEvent(true);if($('#plan-isa'))$('#plan-isa').onclick=()=>{investment={path:'known',name:'Stocks & shares ISA top-up · fund to confirm',amount:recAmount(),source:'cash',goal:'grow',horizon:'Long term'};investReview()};document.querySelectorAll('[data-filing]').forEach(b=>b.onclick=()=>fullFiling(b.dataset.filing))};
window.addEventListener('resize',()=>{if(view()==='home'&&!$('#simple-dialog').open)render()});render();

const plannerOriginalCommand=command;command=function(c){if(c==='review')fullFiling('confirmation');else plannerOriginalCommand(c)};

const plannerReset=$('#reset-simple').onclick;$('#reset-simple').onclick=()=>{journeyFilter='all';journeyRange='full';plannerReset()};
